import { test, expect } from '@playwright/test';
import { blockWrites, expectListFirstOnMobile, LOAD, personalAreaHeading } from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

test.describe('Чат / переписки — вход в /messages на мобайле', () => {
  test('Мобайл: меню «אזור אישי» доступно под списком, «המודעות שלי» открывает /mybusinesses #c5ed06 @android @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto('/messages');
    await expectListFirstOnMobile(page);

    const menu = personalAreaHeading(page);
    await menu.scrollIntoViewIfNeeded();
    await expect(menu, 'меню «אזור אישי» видно после прокрутки').toBeInViewport();
    for (const item of ['המודעות שלי', 'שיחות', 'מועדפים ושיחות', 'שינוי סיסמה']) {
      await expect(page.getByText(item, { exact: true }).last(), `пункт меню «${item}»`).toBeVisible();
    }

    await page.getByText('המודעות שלי', { exact: true }).last().click();
    await page.waitForURL(/\/mybusinesses/, LOAD);
  });
});
